CREATE TABLE IF NOT EXISTS graph_assessments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), node_type text NOT NULL, node_id uuid NOT NULL, state text NOT NULL DEFAULT 'developing', score numeric(6,2), strengths jsonb NOT NULL DEFAULT '[]'::jsonb, dependencies jsonb NOT NULL DEFAULT '[]'::jsonb, risks jsonb NOT NULL DEFAULT '[]'::jsonb, opportunities jsonb NOT NULL DEFAULT '[]'::jsonb, next_actions jsonb NOT NULL DEFAULT '[]'::jsonb, relationship_count integer NOT NULL DEFAULT 0, trusted_relationship_count integer NOT NULL DEFAULT 0, created_by text, created_at timestamptz NOT NULL DEFAULT now());